def main() -> int:
    parser = argparse.ArgumentParser(description="Compile two evidence-grounded zero-budget breakout release candidates.")
    parser.add_argument("--evidence", type=Path, default=EVIDENCE_LEDGER)
    parser.add_argument("--output", type=Path, default=Path("evidence/v10/gtm-breakout-release-candidates-v1.json"))
    args = parser.parse_args()
    evidence = json.loads(args.evidence.read_text(encoding="utf-8"))
    verify_evidence_ledger(evidence)
    portfolio = compile_breakout_portfolio(candidates(evidence["content_sha256"]))
    verify_breakout_portfolio(portfolio)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(portfolio, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"output": str(args.output), "candidate_count": portfolio["candidate_count"], "surface_count": portfolio["surface_count"], "content_sha256": portfolio["content_sha256"]}, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
